def test_only_the_data_root_manifest_is_excluded(repo, data):
    from boxyard import const

    (data / const.BOX_PERMS_MANIFEST_REL_PATH).write_text('{"version":1}')
    (data / "sub" / const.BOX_PERMS_MANIFEST_REL_PATH).write_text('{"nested":true}')

    result = run(push(repo, data))
    _, listing, _ = run(run_restic(repo, ["ls", result.snapshot_id]))
    manifests = [
        line for line in listing.splitlines()
        if line.strip().endswith(const.BOX_PERMS_MANIFEST_REL_PATH)
    ]

    assert len(manifests) == 1, (
        f"expected exactly the NESTED manifest in the snapshot, got {manifests}"
    )
    assert manifests[0].endswith(f"sub/{const.BOX_PERMS_MANIFEST_REL_PATH}")


