def test_a_diff_across_two_source_paths_is_refused_not_acted_on(repo, tmp_path):
    """
    Two snapshots of IDENTICAL content under different paths diff as
    everything-added-and-removed. Acting on that diff deletes the box and
    restores it; the pull must fall back to a full restore instead.
    """
    a = tmp_path / "rootA" / "data"
    b = tmp_path / "rootB" / "data"
    for d in (a, b):
        d.mkdir(parents=True)
        (d / "same.txt").write_text("identical\n")

    snap_a = run(push(repo, a))
    snap_b = run(push(repo, b))
    assert snap_a.source_path != snap_b.source_path

    dest = tmp_path / "dest"
    result = run(
        pull(
            repo,
            dest,
            target_snapshot=snap_b.snapshot_id,
            base_snapshot=snap_a.snapshot_id,
        )
    )

    assert result.mode is PullMode.FULL_PATH_MISMATCH
    assert (dest / "same.txt").read_text() == "identical\n"

