def test_a_full_pull_is_byte_identical(repo, data, tmp_path):
    result = run(push(repo, data))
    dest = tmp_path / "dest"
    outcome = run(
        pull(repo, dest, target_snapshot=result.snapshot_id, base_snapshot=None)
    )
