def test_an_unmodified_replica_with_a_forgotten_base_is_not_modified(repo, data):
    import time

    result = run(push(repo, data))
    synced_at = time.time() + 1  # the tree predates this instant
    run(run_restic(repo, ["forget", result.snapshot_id]))

    assert (
        run(
            local_is_modified(
                repo, data, result.snapshot_id, synced_at_unix=synced_at
            )
        )
        is False
    )


