def test_latest_snapshot_id_follows_the_pushes(repo, data):
    first = run(push(repo, data))
    assert run(latest_snapshot_id(repo)) == first.snapshot_id
    (data / "notes.md").write_text("again\n")
    second = run(push(repo, data, parent=first.snapshot_id))
    assert run(latest_snapshot_id(repo)) == second.snapshot_id


def test_latest_snapshot_id_is_none_for_an_empty_repo(repo):
    assert run(latest_snapshot_id(repo)) is None


def test_the_snapshot_filename_is_the_snapshot_id(repo, data):
    """
    This is what makes the skip filter keyless: a plain listing of `snapshots/`
    names the snapshots without opening the repo.
    """
    result = run(push(repo, data))
    names = {p.name for p in (Path(repo.url) / "snapshots").iterdir()}
    assert result.snapshot_id in names

